js=r'''
const D=DATA, map=document.querySelector('.map'), battle=document.querySelector('.battle'), shell=document.querySelector('.shell'), popup=document.querySelector('.popover');
const query=new URLSearchParams(location.search);let mode=query.get('mode')||'battle', progress=Number(query.get('progress')||.5), pinned=null, inspect=null, timer=null;let camera={x:.50,y:.55,zoom:1}, actors=[];
function img(asset,cl=''){return `<img class="${cl}" src="../assets/${asset}.png" alt="">`}
function art(u){return D.assets[u.templateID]||'monster_slime_portrait'}
function setup(){document.body.classList.toggle('exploration',mode==='map');document.body.classList.toggle('battle-turn-monster',mode==='monster');document.querySelector('.header strong').textContent=mode==='map'?'安然':mode==='monster'?'史莱姆':'晨曦森林守护者小队长安然';document.querySelector('.timer').textContent=mode==='map'?'':mode==='monster'?'◷ 17″':'◷ 17″';document.querySelector('.header small').textContent='第1轮';map.classList.toggle('mini',mode!=='map');map.querySelectorAll('.map-node,.map-unit').forEach(e=>e.remove());
 for(const n of D.nodes){const el=document.createElement('div');el.className='map-node'+(!n.revealed?' unknown':'');el.dataset.node=n.id;el.innerHTML=(n.revealed?img(n.kind==='start'?'node_start':'node_combat'):'?')+`<span class="number">${n.id}</span>`;el.title=n.name;map.append(el)}
 const visible=mode==='map'?D.units.filter(u=>u.player):D.units;for(const u of visible){let el=document.createElement('div');el.className='map-unit'+(mode==='map'&&u.id==='p1'?' walker-wrap':'');el.dataset.unit=u.id;el.innerHTML=(mode==='map'&&u.id==='p1'?'<div class="walker"></div>':img(art(u)))+`<span class="id">${u.id.toUpperCase()}</span>`;map.append(el)}
 battle.querySelectorAll('.actor').forEach(e=>e.remove());for(const [i,u]of D.units.entries()){let el=document.createElement('div');el.className='actor'+(!u.player?' enemy':'')+(u.id===(mode==='monster'?'m1':'p3')?' current':'')+(u.health===0?' down':'')+(u.id==='p6'?' next':'');el.dataset.unit=u.id;el.title=`${u.name} · 生命 ${u.health}/${u.maximumHealth} · 护盾 ${u.shield}`;el.innerHTML=img(art(u))+`<span class="id">${u.id.toUpperCase()}</span><div class="hp" role="progressbar" aria-label="${u.name}生命" aria-valuenow="${u.health}" aria-valuemax="${u.maximumHealth}" aria-valuemin="0"><i style="width:${u.health/u.maximumHealth*100}%"></i></div>`+(u.health===0?'<span class="mark">×</span>':u.id==='p6'?'<span class="mark">◷</span>':'');const spots=[[12,.56],[27,.56],[42,.56],[57,.56],[16,.82],[34,.82],[52,.82],[84,.52],[84,.70],[84,.88]];el.style.left=spots[i][0]+'%';el.style.top=spots[i][1]*100+'%';battle.append(el)}
 document.querySelector('.queue').innerHTML=D.queue.map((id,i)=>{const u=D.units.find(u=>u.id===id);return `<div class="q ${id===(mode==='monster'?'m1':'p3')?'current':''}" data-id="${id}">${img(art(u))}<span class="qid">${id.toUpperCase()}</span>${u.health===0?'<b class="qm">×</b>':id==='p6'?'<b class="qm">◷</b>':i<D.queue.indexOf(mode==='monster'?'m1':'p3')?'<b class="qm">✓</b>':''}</div>`}).join('');document.querySelector('.queue-line').style.setProperty('--acted',D.queue.indexOf(mode==='monster'?'m1':'p3')/9*100+'%');layout();}
function projection(n){const w=map.clientWidth,h=map.clientHeight,scale=mode==='map'?Math.min(w*.71,h*1.32)*camera.zoom:Math.min(w*1.9,h*1.3)*camera.zoom;return {x:w*(mode==='map'?.5:.53)+(n.x-camera.x)*scale,y:h*.56+(n.y-camera.y)*scale,scale};}
function layout(){const w=map.clientWidth,h=map.clientHeight;const bh=battle.clientHeight;for(const e of battle.querySelectorAll('.actor')){const enemy=e.classList.contains('enemy'),ih=Math.max(48,Math.min(enemy?100:(innerWidth<=1500?114:132),bh*(enemy?.18:.26)-42));e.style.height=(ih+32)+'px';e.querySelector('img').style.height=ih+'px';}const nodes=D.nodes.map(n=>({...n,...projection(n)}));let roads='';for(const [a,b]of D.roads){const na=nodes.find(n=>n.id===a),nb=nodes.find(n=>n.id===b);if(na.revealed&&nb.revealed)roads+=`M${na.x} ${na.y}L${nb.x} ${nb.y}`}
 const n1=nodes[0],n2=nodes[1];map.querySelector('svg').setAttribute('viewBox',`0 0 ${w} ${h}`);map.querySelector('svg').innerHTML=`<path class="road-under" d="${roads}"/><path class="road-top" d="${roads}"/>`+(mode==='map'?`<path class="committed-road" d="M${n1.x} ${n1.y}L${n1.x+(n2.x-n1.x)*progress} ${n1.y+(n2.y-n1.y)*progress}"/>`:'');
 for(const n of nodes){const el=map.querySelector(`[data-node="${n.id}"]`);el.style.left=n.x+'px';el.style.top=n.y+'px';el.hidden=n.x<-42||n.x>w+42||n.y<-42||n.y>h+42}
 const off=[[-45,-6],[0,-6],[45,-6],[-65,61],[0,61],[65,61],[0,123],[-50,177],[0,177],[50,177]];
 for(const [i,u]of D.units.entries()){const el=map.querySelector(`[data-unit="${u.id}"]`);if(!el)continue;let n=nodes[1], x=n.x+off[i][0]*(mode==='map'?1:.72),y=n.y+off[i][1]*(mode==='map'?1:.60);if(mode==='map'&&u.id==='p1'){x=n1.x+(n2.x-n1.x)*progress;y=n1.y+(n2.y-n1.y)*progress}else if(mode==='map'&&['p6','p7'].includes(u.id)){n=nodes[4];x=n.x+(u.id==='p6'?-25:25);y=n.y+20}el.style.left=x+'px';el.style.top=y+'px';el.hidden=x<35||x>w-35||y<80||y>h-12;}
 map.querySelector('.edge').style.display=mode!=='map'?'block':'none';place();}
const details={runeSlash:['符文斩','2行动点 · 单敌 · 射程1 · 余2次','目标伤害2D12+2；自身恢复4生命、护盾4','行动点不足'],runeWard:['符文庇护','2行动点 · 节点全部队友 · 射程1 · 余2次','目标恢复8生命、护盾6','行动点不足'],battleRune:['战斗符文','1行动点 · 节点全部队友 · 射程1 · 余2次','目标护盾4；伤害+3，持续2轮','可用'],smallPotion:['小治疗药水','1行动点 · 自己/队友 · 射程1 · 持有2','恢复6生命；普通治疗不能救起倒地目标','可用'],shieldPotion:['护盾药水','1行动点 · 射程1 · 持有1','护盾8，与旧护盾取较高值','可用'],revivalStone:['复活石','2行动点 · 同节点倒地队友 · 持有1','复活半最大生命；当轮不能行动，下轮按原队列行动','行动点不足']};
function place(){if(!inspect||popup.hidden)return;const b=document.querySelector(`[data-entry="${inspect}"]`).getBoundingClientRect(),s=document.querySelector('.resources').getBoundingClientRect(),pw=popup.offsetWidth,left=Math.max(s.right+20,Math.min(innerWidth-48-pw,b.x+b.width/2-pw/2));popup.style.left=left+'px';popup.style.top=b.top-popup.offsetHeight-12+'px';popup.style.setProperty('--arrow',Math.max(12,Math.min(pw-26,b.x+b.width/2-left-9))+'px');}
function show(id,pin=false){if(mode==='map'||mode==='monster')return;clearTimeout(timer);inspect=id;if(pin)pinned=id;shell.classList.add('inspecting');popup.hidden=false;const d=details[id];popup.querySelector('strong').textContent=d[0];popup.querySelector('.meta').textContent=d[1];popup.querySelector('.effect').textContent=d[2];popup.querySelector('.reason').textContent=d[3];document.querySelectorAll('.entry').forEach(b=>{b.classList.toggle('selected',b.dataset.entry===id);b.setAttribute('aria-expanded',b.dataset.entry===id?'true':'false')});layout();}
function close(){clearTimeout(timer);inspect=null;pinned=null;popup.hidden=true;shell.classList.remove('inspecting');document.querySelectorAll('.entry').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-expanded','false')});layout();}
for(const b of document.querySelectorAll('.entry')){b.onpointerenter=()=>{clearTimeout(timer);if(!pinned)show(b.dataset.entry)};b.onfocus=()=>{if(!pinned)show(b.dataset.entry)};b.onpointerleave=()=>{if(!pinned)timer=setTimeout(()=>{if(document.activeElement!==b)close()},150)};b.onblur=()=>{if(!pinned)close()};b.onclick=()=>pinned===b.dataset.entry?close():show(b.dataset.entry,true);}
popup.onpointerenter=()=>clearTimeout(timer);popup.onpointerleave=()=>{if(!pinned)timer=setTimeout(close,150)};popup.querySelector('.close').onclick=close;document.onkeydown=e=>{if(e.key==='Escape')close()};document.addEventListener('pointerdown',e=>{if(pinned&&!e.target.closest('.entry,.popover'))close()});
document.querySelector('[data-control="play"]').onclick=()=>playMove();document.querySelector('[data-control="focus"]').onclick=()=>{camera={x:.36,y:.55,zoom:1.25};layout()};document.querySelector('[data-control="overview"]').onclick=()=>{camera={x:.50,y:.55,zoom:1};layout()};document.querySelector('[data-control="zoom"]').onclick=()=>{camera.zoom=camera.zoom===1?1.3:1;layout()};
let playing=false;async function playMove(){if(playing)return;playing=true;close();mode='map';progress=0;camera={x:.50,y:.55,zoom:1};setup();const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches||document.body.classList.contains('reduce');if(!reduced){const start=performance.now();await new Promise(resolve=>{function step(t){progress=Math.min(1,(t-start)/1800);layout();if(progress<1)requestAnimationFrame(step);else resolve()}requestAnimationFrame(step)})}progress=1;layout();await new Promise(resolve=>setTimeout(resolve,reduced?0:180));mode='battle';camera={x:.36,y:.55,zoom:1};setup();playing=false;}
window.sample={setMode(m){close();mode=m;camera={x:m==='map'?.50:.36,y:.55,zoom:1};setup()},setProgress(p){progress=p;layout()},show,close,playMove,get mode(){return mode},get progress(){return progress},engineCalls:0};window.addEventListener('resize',layout);camera.x=mode==='map'?.50:.36;setup();
'''.replace('DATA',data)
entries=[('runeSlash','✦','符文斩',None),('runeWard','◇','庇护',None),('battleRune','✧','符文',None),('smallPotion','','药水','item_small_potion'),('shieldPotion','','护盾','item_shield_potion'),('revivalStone','','复活石','item_revival_stone')]
cards=''.join(f'<button class="entry glass" data-entry="{id}" aria-label="公开查看{label}完整详情" aria-expanded="false">'+(f'<img src="../assets/{asset}.png" alt="">' if asset else f'<span class="glyph">{glyph}</span>')+f'<span>{label}</span>'+('<span class="quantity">×'+('2' if id=='smallPotion' else '1')+'</span>' if asset else '')+'</button>' for id,glyph,label,asset in entries)
diamonds=''.join('<svg class="diamond '+('filled' if i==0 else '')+'" viewBox="0 0 20 24"><path d="M10 2L18 12L10 22L2 12Z"/></svg>' for i in range(8))
doc='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>晴空学园 HD像素地图与战斗显示样板</title><link rel="stylesheet" href="../sources/sample.css"><body><div class="ambient"></div><main class="shell"><header class="header frost"><span class="seal">✧</span><strong></strong><span><small></small><span class="timer"></span></span></header><div class="main"><section class="scene map" aria-label="实际节点与道路显示样板"><div class="environment"></div><svg class="roads"></svg><div class="controls">'+''.join(f'<button class="glass" data-control="{id}" aria-label="{label}">{glyph}</button>' for id,label,glyph in [('focus','回到当前节点','⌖'),('overview','地图总览','⛶'),('zoom','缩放','＋'),('play','播放一次已提交移动的显示示意','▷')])+'</div><div class="edge">'+ '<img src="../assets/node_combat.png" alt="">↗ 3</div></section><section class="scene battle" aria-label="同节点战斗阵位"><div class="environment"></div></section></div><section class="queue-panel frost" aria-label="完整混合回合轨道"><div class="queue-line"></div><div class="queue"></div></section><section class="dock frost"><div class="resources"><div class="resource-values"><span class="blue-mark" aria-label="蓝队"></span><span aria-label="金币0">◉ 0</span><span aria-label="积分0">★ 0</span></div><div class="ap" aria-label="行动力1，上限8">'+diamonds+'</div></div><div class="entries">'+cards+'</div></section></main><aside class="popover" hidden><button class="close glass" aria-label="关闭详情">×</button><strong></strong><p class="meta"></p><p class="effect"></p><p class="reason"></p></aside><script src="../sources/sample.js"></script></body></html>'
(R/'sources/sample.css').write_text(css.strip()+'\n');(R/'sources/sample.js').write_text(js.strip()+'\n');(R/'previews/sample.html').write_text(doc+'\n')

async def export():
    reports=[]
    embedded_doc=None
    async with async_playwright() as p:
        b=await p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
        for ratio,width,height in [('16x9',1920,1080),('4x3',1440,1080)]:
            page=await b.new_page(viewport={'width':width,'height':height},device_scale_factor=1)
            await page.route('http**/*',lambda route:route.abort())
            embedded=doc.replace('<link rel="stylesheet" href="../sources/sample.css">','<style>'+css+'</style>').replace('<script src="../sources/sample.js"></script>','<script>'+js+'</script>')
            for asset in (R/'assets').glob('*.png'):
                embedded=embedded.replace('../assets/'+asset.name,'data:image/png;base64,'+base64.b64encode(asset.read_bytes()).decode())
            # JS builds sprite URLs at runtime; use an in-memory asset lookup for screenshots.
            lookup={p.stem:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in (R/'assets').glob('*.png')}
            embedded=embedded.replace('const D=', 'const ASSET_URLS='+json.dumps(lookup)+';const D=').replace('src="../assets/${asset}.png"','src="${ASSET_URLS[asset]}"')
            embedded_doc=embedded
            await page.set_content(embedded);await page.evaluate('document.fonts.ready');await page.wait_for_timeout(100)
            for mode in ['map','battle','monster']:
                await page.evaluate('(m)=>window.sample.setMode(m)',mode)
                await page.wait_for_timeout(100)
                await page.screenshot(path=str(R/'previews'/f'{mode}_{ratio}.png'))
                report=await page.evaluate('''()=>({mode:sample.mode,actorCount:document.querySelectorAll('.battle .actor').length,queueCount:document.querySelectorAll('.q').length,ratio:document.querySelector('.battle').clientWidth/document.querySelector('.map').clientWidth,sceneHeight:document.querySelector('.map').clientHeight,headerOverflow:document.querySelector('.header strong').scrollWidth>document.querySelector('.header strong').clientWidth+1,entryOverflow:[...document.querySelectorAll('.entry')].some(e=>e.scrollWidth>e.clientWidth+1),actorsInside:[...document.querySelectorAll('.battle .actor')].every(e=>{const a=e.getBoundingClientRect(),s=document.querySelector('.battle').getBoundingClientRect();return a.x>=s.x&&a.right<=s.right&&a.top>=s.top&&a.bottom<=s.bottom}),filledAP:document.querySelectorAll('.diamond.filled').length,emptyAP:document.querySelectorAll('.diamond:not(.filled)').length,engineCalls:sample.engineCalls})''')
                report['aspect']=ratio
                if mode!='map':assert abs(report['ratio']-7/3)<.012 and report['actorsInside'],report
                assert not report['headerOverflow'] and not report['entryOverflow'],report
                reports.append(report)
            await page.evaluate('sample.setMode("battle");sample.show("runeSlash",true)');await page.wait_for_timeout(80)
            await page.screenshot(path=str(R/'previews'/f'battle_detail_{ratio}.png'))
            check=await page.evaluate('''()=>{const p=document.querySelector('.popover').getBoundingClientRect(),b=document.querySelector('[data-entry=runeSlash]').getBoundingClientRect(),q=document.querySelector('.queue-panel').getBoundingClientRect();return {aboveCard:p.bottom<b.top,belowTrack:p.top>q.bottom,withinScreen:p.x>=0&&p.right<=innerWidth,ratio:document.querySelector('.battle').clientWidth/document.querySelector('.map').clientWidth}}''');assert check['aboveCard'] and check['belowTrack'] and check['withinScreen'],check
            reports.append({'aspect':ratio,'detail':check})
            for id,_,_,_ in entries:
                await page.evaluate('(id)=>sample.show(id,true)',id)
                bound=await page.evaluate('''()=>{const p=document.querySelector('.popover').getBoundingClientRect(),q=document.querySelector('.queue-panel').getBoundingClientRect(),a=document.querySelector('.entry.selected').getBoundingClientRect();return {aboveCard:p.bottom<a.top,belowTrack:p.top>q.bottom,withinScreen:p.x>=0&&p.right<=innerWidth}}''')
                assert all(bound.values()),(ratio,id,bound)
            await page.keyboard.press('Escape');assert await page.locator('.popover').is_hidden()
            await page.evaluate('sample.close();sample.setMode("map");sample.setProgress(.5)');await page.wait_for_timeout(50)
            await page.screenshot(path=str(R/'previews'/f'map_move_midpoint_{ratio}.png'))
            await page.evaluate('document.body.classList.add("reduce");sample.playMove()');await page.wait_for_timeout(100)
            assert await page.evaluate('sample.mode')=='battle'
            await page.close()
        context=await b.new_context(viewport={'width':1920,'height':1080},record_video_dir=str(R/'evidence/video-temp'),record_video_size={'width':1280,'height':720})
        page=await context.new_page();await page.route('http**/*',lambda route:route.abort());await page.set_content(embedded_doc);await page.evaluate('sample.setMode("map");sample.setProgress(0)');await page.wait_for_timeout(300)
        await page.evaluate('sample.playMove()');await page.wait_for_timeout(800)
        assert await page.evaluate('sample.mode')=='battle'
        video=page.video;await context.close();await video.save_as(str(R/'previews/map_move_to_battle_16x9.webm'));await video.delete()
        import shutil
        shutil.rmtree(R/'evidence/video-temp')
        await b.close()
    (R/'evidence/browser-checks.json').write_text(json.dumps({'status':'pass','checks':reports,'sixPopoverAnchorsBothAspects':'pass','escapeClose':'pass','reducedMotionArrivalToBattle':'pass','offlineHTTPBlocked':True,'movementVideo':'previews/map_move_to_battle_16x9.webm','limits':'HTML/CSS display fixture; not engine or native glass validation'},ensure_ascii=False,indent=2)+'\n')
asyncio.run(export())
